const CODE="0313"; // ganti sesuai jawaban teka-teki
const $=id=>document.getElementById(id);
const lock=$("lock"),pass=$("pass"),dotsEl=$("dots"),msg=$("msg"),pad=$("pad"),wall=$("wall"),island=$("island"),root=document.documentElement,phone=$("phone");
let entry="",tries=0,startY=null,dy=0;
const wi=wall.querySelector("img"),bi=wi.cloneNode();bi.className="b";wall.appendChild(bi);
const setBlur=p=>phone.style.setProperty("--p",Math.max(0,Math.min(1,p)));
const letters={2:"ABC",3:"DEF",4:"GHI",5:"JKL",6:"MNO",7:"PQRS",8:"TUV",9:"WXYZ"};
[1,2,3,4,5,6,7,8,9,"",0,"Batal"].forEach(v=>{
  if(v===""){pad.appendChild(document.createElement("span"));return}
  const b=document.createElement("button");
  if(v==="Batal"){b.className="k t";b.textContent="Batal";b.onclick=closePass}
  else{b.className="k";b.innerHTML=v+"<small>"+(letters[v]||"&nbsp;")+"</small>";b.onclick=()=>press(String(v))}
  pad.appendChild(b);
});
const draw=()=>[...dotsEl.children].forEach((d,i)=>d.classList.toggle("f",i<entry.length));
function openPass(){pass.hidden=false;pass.style.transition="opacity .3s";pass.style.opacity=1;lock.classList.remove("drag");wall.classList.remove("live");lock.style.transform="";lock.classList.add("gone");setBlur(1)}
function closePass(){entry="";draw();msg.textContent="";lock.classList.remove("gone");setBlur(0);setTimeout(()=>{if(!lock.classList.contains("gone"))pass.hidden=true},400)}
function press(d){
  if(entry.length>=4)return;entry+=d;draw();
  if(entry.length<4)return;
  setTimeout(()=>{
    if(entry===CODE){pass.style.transition="opacity .5s";pass.style.opacity=0;setBlur(0);setTimeout(()=>{pass.hidden=true;$("home").hidden=false},500)}
    else{tries++;dotsEl.classList.remove("shake");void dotsEl.offsetWidth;dotsEl.classList.add("shake");
      if(navigator.vibrate)navigator.vibrate(200);
      msg.textContent=tries>=3?"Jam itu berhenti bukan tanpa alasan.":"Kode salah. Coba lagi.";entry="";draw()}
  },180);
}
lock.addEventListener("pointerdown",e=>{startY=e.clientY;dy=0;lock.classList.add("drag");wall.classList.add("live");lock.setPointerCapture(e.pointerId);pass.style.transition="none";pass.style.opacity=0;pass.hidden=false});
let raf=0;
lock.addEventListener("pointermove",e=>{if(startY===null)return;dy=Math.min(0,e.clientY-startY);if(raf)return;raf=requestAnimationFrame(()=>{raf=0;lock.style.transform="translate3d(0,"+dy+"px,0)";lock.style.opacity=1+dy/400;pass.style.opacity=Math.min(1,-dy/140);setBlur(-dy/130)})});
function end(){
  if(startY===null)return;cancelAnimationFrame(raf);raf=0;const m=dy;startY=null;lock.classList.remove("drag");wall.classList.remove("live");lock.style.opacity="";
  if(m<-110)openPass();
  else{lock.style.transform="";pass.style.transition="opacity .3s";pass.style.opacity=0;setBlur(0);setTimeout(()=>{if(!lock.classList.contains("gone"))pass.hidden=true},400)}
}
lock.addEventListener("pointerup",end);lock.addEventListener("pointercancel",end);
document.addEventListener("keydown",e=>{
  if(!pass.hidden&&/^\d$/.test(e.key))press(e.key);
  else if(pass.hidden&&(e.key==="ArrowUp"||e.key===" ")){pass.hidden=false;openPass()}
});

