function scare(face){
  try{const t=actx.currentTime,n=actx.createBufferSource(),b=actx.createBuffer(1,actx.sampleRate*.7,actx.sampleRate),d=b.getChannelData(0);
    for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);
    const g=actx.createGain();g.gain.value=.9;n.buffer=b;n.connect(g);g.connect(actx.destination);n.start(t);
    const o=actx.createOscillator();o.type="sawtooth";o.frequency.setValueAtTime(900,t);o.frequency.exponentialRampToValueAtTime(70,t+.6);
    const g2=actx.createGain();g2.gain.value=.5;o.connect(g2);g2.connect(actx.destination);o.start(t);o.stop(t+.7)}catch(e){}
  if(navigator.vibrate)navigator.vibrate([300,50,300]);
  const d=document.createElement("div");d.className="scare";d.textContent=face||"👹";phone.appendChild(d);setTimeout(()=>d.remove(),950);
}
