function mkApp(k){const a=APPS[k],b=document.createElement("button");b.className="app";b.dataset.app=k;
  b.innerHTML='<span class="ic" style="background:'+a.bg+'">'+a.i+'</span><em>'+a.n+'</em>'+(a.b?'<b class="badge">'+a.b+'</b>':"");
  b.onclick=()=>{
    if(k==="fo"){openGal();return}
    if(APPV[k]){openAv(k);return}
    if(k==="wa"){openWA()}
    else{b.classList.remove("no");void b.offsetWidth;b.classList.add("no")}
  };return b}
