const sleepEl=$("sleep");let actx;
const nbox=document.querySelector(".notifs"),notes=[...nbox.querySelectorAll(".n")];notes.forEach(n=>n.remove());
function ping(){
  try{
    const t=actx.currentTime;
    [[1318.5,0],[1568,.11]].forEach(([f,d])=>{
      const o=actx.createOscillator(),g=actx.createGain();
      o.type="sine";o.frequency.value=f;
      g.gain.setValueAtTime(0,t+d);g.gain.linearRampToValueAtTime(.25,t+d+.01);g.gain.exponentialRampToValueAtTime(.001,t+d+.7);
      o.connect(g);g.connect(actx.destination);o.start(t+d);o.stop(t+d+.75);
    });
  }catch(e){}
  if(navigator.vibrate)navigator.vibrate([40,40,40]);
}
sleepEl.addEventListener("pointerdown",()=>{
  try{actx=new (window.AudioContext||window.webkitAudioContext)();actx.resume();startBgm();loadSfx()}catch(e){}
  sleepEl.classList.add("off");setTimeout(()=>sleepEl.remove(),700);
  notes.slice().reverse().forEach((n,i)=>setTimeout(()=>{
    const w=document.createElement("div"),x=document.createElement("div");
    w.className="nw";x.className="nx";x.appendChild(n);w.appendChild(x);nbox.prepend(w);
    requestAnimationFrame(()=>requestAnimationFrame(()=>w.classList.add("show")));ping();
  },1100+i*1500));
  setTimeout(startSpam,8500);
},{once:true});

