const sp={i:0,stop:false};
function startSpam(){
  const bn=document.createElement("div");bn.className="bn";
  bn.innerHTML='<div class="ic"><svg viewBox="0 0 32 32"><path fill="#fff" d="M16 4a12 12 0 0 0-10.300 18L4 28l6.200-1.600A12 12 0 1 0 16 4z"/></svg></div><div><b>Rara 🎀</b><p></p></div>';
  phone.appendChild(bn);
  const hide=()=>bn.classList.remove("show");
  bn.onclick=()=>{hide();$("home").hidden||openWA()};
  lock.addEventListener("pointerdown",hide);
  const next=()=>{
    if(sp.stop||sp.i>=SPAM.length){bn.remove();return}
    const last=sp.i===SPAM.length-1,quiet=!pass.hidden;
    bn.querySelector("p").textContent=SPAM[sp.i++];
    ping();
    if(!quiet)bn.classList.add("show");
    setTimeout(hide,last?4000:1000);
    setTimeout(next,last?4600:2000);
  };
  next();
}

