const SPAM=["Put","PUT","PUUUT","lu dimana","angkat telepon gua","BUKA PINTUNYA","gua udah ngetok dari tadi","kok ga dibales","centang dua doang","lu denger gua ga","Put please","jangan becanda","gua takut","bales dong"];
async function spam(){
  sp.stop=true;const d=document.querySelector(".bn");if(d)d.remove();
  await wait(300);
  for(let j=0;j<SPAM.length;j++){if(j>=sp.i){await wait(420+Math.random()*250);if(navigator.vibrate)navigator.vibrate(30)}bub(SPAM[j],false)}
  await wait(1100);bub("apaan",true);await wait(900);
}
function openWA(){chat.hidden=false;const g=document.querySelector('[data-app=wa] .badge');if(g)g.remove();if(!started){started=true;spam().then(()=>play("start"))}}
